{"results": [{"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 1.203, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-039 (0.76)"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-015", "label": "Study family SF-APPS-015: Player BEST/AVOID tier tendency in H2 trigger games (55 series)", "score": 0.908, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-015 (0.80)"], "attributes": {"observed_research_question": "Player BEST/AVOID tier tendency in H2 trigger games (55 series)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams and players differ in how often H2 trigger possessions land on the engine's BEST vs AVOID counter.", "observed_result": "Team AVOID% ranges 50.6% (ORL) to 6.8% (SAC); team BEST% 0.0%-15.8%.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No outcome test; player samples 10-178 possessions.", "observed_sample_and_power": "min 10 poss per player", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "trigger_table_clean.csv, 55 series 2022-2026, 179 players, 25 teams, min 10 poss.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-048"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-001"}]}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.883, "reached_via": ["FAM:SF-APPA-005 auto_related_family (record_link_related_to) FAM:SF-APPA-001", "FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-001"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.772, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-005 (0.77)"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF-APPS-070", "label": "Study family SF-APPS-070: H1 usage as predictor of H2 suppression (distribution shift)", "score": 0.747, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-070 (0.75)"], "attributes": {"observed_research_question": "H1 usage as predictor of H2 suppression (distribution shift)", "auto_outcome_status": "rejected", "observed_hypothesis": "First-half reliance on a play type predicts second-half suppression after controlling for H1 PPP / mean reversion.", "observed_result": "Test B: all BH-adjusted null/WEAK (PNR ATT=+0.0313 BH_p=0.0658 WEAK; others NULL). Test C top-1 acc=0.550 vs mean-reversion baseline 0.511 (+0.039) vs most-used 0.239. Test A PULL_UP slope -0.0581 p=0.0030; CUT -0.0917 p [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Matched ATT does not survive BH; predictive lift over mean reversion is only +0.039 (0.550 vs 0.511). Bulk of H2 suppression is RTM.", "observed_sample_and_power": "n=8873 team-games; Test C test n=1008"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:RTM_SELECTION"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.562, "reached_via": ["request matches RQC:RQC-122 (0.71); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-122", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.71); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPS-092", "label": "Study family SF-APPS-092: HasConn share vs pace (possessions per 48)", "score": 0.559, "reached_via": ["request matches RQC:RQC-119 (0.71); FAM:SF-APPS-092 auto_addresses_question RQC:RQC-119", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.71); FAM:SF-APPS-092 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "HasConn share vs pace (possessions per 48)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Connector presence slows pace (substituting half-court organization for transition).", "observed_result": "beta(HasConn share -> poss/48)=-0.86 SE=0.38 t=-2.25 p=0.0266; within-ts corr=-0.002 p=0.782. Mix: TRANSITION -0.448 pp p=0.0013; PNR +0.980 p=0.00187; CUT +1.353 p=1.2e-11; DRIVE -0.542 p=0.0206; SPOT_UP -1.248 p=0.0003 [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Pace beta p=0.0266 but within-ts correlation is 0; no stint clock so poss/48 is period-implied. Mix shifts are clearer than efficiency.", "observed_sample_and_power": "n=28569 periods; mix n_ts=73", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-087"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.558, "reached_via": ["request matches RQC:RQC-101 (0.71); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-101", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.71); FAM:SF-APPS-012 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPS-036", "label": "Study family SF-APPS-036: Player-level BEST vs AVOID PPP gap (initiators, 55-series)", "score": 0.509, "reached_via": ["FAM:SF-APPS-015 auto_related_family (record_link_related_to) FAM:SF-APPS-036", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.71); FAM:SF-APPS-036 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Player-level BEST vs AVOID PPP gap (initiators, 55-series)", "auto_outcome_status": "supported", "observed_hypothesis": "The team-level BEST vs AVOID gap holds when H2 possessions are filtered to initiating player.", "observed_result": "Mean gap (n>=10 each tier) +0.427 PPP. Mean BEST 1.347 (38 players) vs AVOID 0.920 (94 players). Stars mean gap +0.542 (n=15) vs role +0.428 (n=16). Only 3 players clear n>=30 both tiers (all BOS: White +0.864, Brown +0. [cut; read_family for the full text]", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Pooled player gap +0.427 in the same direction as the team gap; most star cells are below the n>=30 gate.", "observed_sample_and_power": "38/94 players at n>=15; only 3 at n>=30 both tiers", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-030", "label": "Study family SF-APPA-030: Play-type label backfill verification", "score": 0.497, "reached_via": ["FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-030", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.71); FAM:SF-APPA-030 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Play-type label backfill verification", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Backfilled play-type labels match expected league distributions and team identities.", "observed_result": "PNR 28.7% FAIL (band 20-28%); PULL_UP 7.9% FAIL; 3100 games with team PNR >33% FAIL; PNR PPP 0.948 PASS; temporal PASS; team identity FAIL; 2024-25 PULL_UP ~0-1% for many teams. Final: FAIL.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "2024-25 PULL_UP shares 0.0-2.0% for many teams; 82.8% of PNR labels proxy_calibrated.", "observed_sample_and_power": "921,514 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-001"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}]}], "n_results": 10}

Stage 2. Using the retrieval result above (follow-up tools are allowed within the tool budget), complete steps 4 to 9
and reply with the final action. Output schema (all fields required):
{
 "research_concepts": [
  "concept"
 ],
 "methodological_questions": [
  "question"
 ],
 "historical_evidence": [
  {
   "id": "identifier of a record returned by a tool",
   "status_as_recorded": "outcome status exactly as stated in the record (supported | rejected | inconclusive | untestable | artifact | not a hypothesis test | no result recorded)",
   "finding": "what the record states, in its own terms"
  }
 ],
 "failed_approaches": [
  {
   "id": "identifier of a returned record",
   "what_failed": "approach",
   "why": "failure mechanism or limitation as recorded"
  }
 ],
 "evidence_establishes": [
  "what the retrieved evidence establishes for this question"
 ],
 "evidence_does_not_establish": [
  "what it leaves open or cannot show"
 ],
 "own_inferences": [
  "your inference, not stated in any record"
 ],
 "uncertainties": [
  "uncertainty or missing information"
 ],
 "historical_effect": {
  "changed_decision": "yes | no | no_historical_evidence",
  "explanation": "whether and how the historical evidence changed the decision"
 },
 "testability": {
  "p_testable": "number in [0,1]: probability the question can be answered with the stated data at useful power",
  "blocking_constraints": [
   {
    "code": "one of RISK_CODES",
    "text": "string"
   }
  ]
 },
 "prior_work": {
  "already_answered": "yes | partly | no | unknown",
  "cited": [
   "identifiers of prior work relied on"
  ],
  "summary": "string"
 },
 "risks": [
  {
   "code": "one of RISK_CODES",
   "text": "string"
  }
 ],
 "predicted_outcome": {
  "supported": "probability",
  "rejected": "probability",
  "untestable": "probability",
  "artifact": "probability",
  "uncertain": "probability"
 },
 "decision": "proceed | proceed_with_changes | do_not_proceed",
 "design": {
  "estimand": "string",
  "unit": "string",
  "sample": "string",
  "power": "string",
  "controls": "string",
  "falsification": "string",
  "multiplicity": "string",
  "decision_rule": "string",
  "data_version": "string"
 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{
 "research_concepts": [
  "defensive suppression of opponent H2-H1 scoring change",
  "team-level defensive effect as a persistent trait versus regression to the mean",
  "counter strategy (BEST/AVOID) tiers and their link to defensive outcomes",
  "play-type labels derived from play-by-play and their validity"
 ],
 "methodological_questions": [
  "Is the team-level defensive effect on opponents' H2-H1 change stable across seasons (year-over-year or split-season reliability) when estimated from raw scoring rather than derived play-type labels?",
  "How much of the H2 suppression signal is regression to the mean, and does a reliability estimate survive RTM and opponent-quality adjustment?",
  "What sample size (team-seasons, possessions, games) is needed to detect a reliability coefficient of plausible size with 120 team-seasons?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-070",
   "status_as_recorded": "rejected",
   "finding": "H1 play-type usage as a predictor of H2 suppression: matched ATT for PNR did not survive BH correction (ATT +0.0313, BH_p 0.0658, WEAK; others NULL). Predictive lift over mean reversion was small (0.550 vs 0.511). Record states the bulk of H2 suppression is RTM. Sample n=8873 team-games."
  },
  {
   "id": "FAM:SF-APPA-030",
   "status_as_recorded": "inconclusive",
   "finding": "Play-type label backfill verification returned FAIL: PNR 28.7% (band 20-28%), PULL_UP 7.9% FAIL, team identity FAIL, 2024-25 PULL_UP ~0-1% for many teams, 82.8% of PNR labels proxy_calibrated. Final verdict FAIL over 921,514 possessions."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Inferred defensive scheme-change labels: within-game change 61.0%, cross-game change 67.7%, transition matrices near-uniform. Record's own caveat: the inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform matrices are consistent with label noise."
  },
  {
   "id": "FAM:SF-CHT-039",
   "status_as_recorded": "inconclusive",
   "finding": "AVOID share vs winning: game-level rho=-0.19 p=0.008 (inflated n, team-quality confound); series-level rho=-0.26 p=0.07 with n=50, underpowered (about 80 series needed for p<0.05). Record notes team-quality confounding remains."
  },
  {
   "id": "FAM:SF-APPA-001",
   "status_as_recorded": "artifact",
   "finding": "A1 adaptation falsification: apparent adapter PPP lift did not hold under asymmetry, confidence and carryover tests (next-game PPP Welch p=0.842). Record classifies the apparent effect as a construction, selection or labelling artifact."
  },
  {
   "id": "FAM:SF-APPS-012",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Defensive PPP allowed and opponent possession share, RS vs playoffs, 25 teams: DRIVE allowed 1.191 to 0.923; PNR share +12.1pp, which the record says may reflect tagging differences. Descriptive only, no inferential test."
  },
  {
   "id": "FAM:SF-APPS-036",
   "status_as_recorded": "supported",
   "finding": "Player-level BEST vs AVOID PPP gap in H2 initiator possessions: mean gap +0.427 PPP (n>=10 per tier), same direction as team-level gap. Only 3 players clear n>=30 in both tiers. Concerns player-initiator gaps, not team-level reliability."
  },
  {
   "id": "FAM:SF-APPS-015",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Player BEST/AVOID tier tendency in H2 trigger games (55 series, 25 teams): team AVOID% ranges 50.6% (ORL) to 6.8% (SAC). Descriptive; player samples 10 to 178 possessions; mechanism unclear per record."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPA-030",
   "what_failed": "Using backfilled play-type labels as the basis for defensive or H2 analyses",
   "why": "Label verification FAILED on league distribution and team identity checks; most PNR labels were proxy-calibrated and 2024-25 PULL_UP shares were near zero for many teams (labelling artifact)."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Measuring defensive scheme change from inferred labels",
   "why": "Inferred labels cannot separate defensive adjustment from offensive execution; near-uniform transitions and 99% change rates are consistent with label noise."
  },
  {
   "id": "FAM:SF-APPA-001",
   "what_failed": "Treating an apparent adapter PPP lift as a real defensive coverage response",
   "why": "Lift reversed or vanished under asymmetry, confidence and carryover tests; recorded as a construction, selection or labelling artifact, with regression-to-the-mean limitation."
  },
  {
   "id": "FAM:SF-APPS-070",
   "what_failed": "H1 usage as a predictor of H2 suppression beyond mean reversion",
   "why": "Matched effect did not survive multiple-testing correction; predictive lift over RTM baseline was only +0.039. Record attributes most H2 suppression to RTM."
  },
  {
   "id": "FAM:SF-CHT-039",
   "what_failed": "Series-level AVOID share as a predictor of winning independent of team quality",
   "why": "Series n=50 underpowered (p=0.07) and team-quality confounded; game-level significance was inflated by non-independent observations."
  }
 ],
 "evidence_establishes": [
  "Earlier project work on closely related H2 suppression and defensive-tier questions has not produced a validated, reliable team-level defensive trait; the closest tests were rejected, artifact, or inconclusive.",
  "Derived play-type labels in this data are unreliable for at least some seasons and teams (FAIL verdict in SF-APPA-030), so any design that depends on them is at risk.",
  "Regression to the mean is recorded as the dominant component of H2 suppression signals (SF-APPS-070), so an unadjusted H2-H1 effect is likely to look reliable for artifactual reasons.",
  "Team-quality confounding and small-n series analyses were already identified as obstacles for AVOID-share questions (SF-CHT-039).",
  "No retrieved record tests split-season or year-over-year reliability of a team-level defensive effect on opponents' H2-H1 change."
 ],
 "evidence_does_not_establish": [
  "Whether a team-level defensive effect on opponents' H2-H1 change is a reliable trait; no retrieved record estimates a reliability coefficient for it.",
  "Whether the raw H2-H1 scoring measure (without play-type labels) has adequate reliability across the 120 team-seasons.",
  "The magnitude of true between-team variance in the H2-H1 defensive effect or the power needed to detect it.",
  "Whether the player-level BEST/AVOID gap (SF-APPS-036) generalizes to team-level reliability.",
  "Anything about 2025-26 playoff data, which is partial before 2026-06-21 and is not covered by the retrieved records."
 ],
 "own_inferences": [
  "The question can be reframed as a split-season reliability test on raw points allowed, which avoids the failed play-type labels.",
  "With 30 teams and 4 seasons (120 team-seasons), there are roughly 90 consecutive-season pairs; this gives moderate power only for reliability coefficients around 0.3 or larger, and H2-H1 team-season means are likely noisy.",
  "A reliability estimate that is not compared with an RTM null (shuffled or matched-baseline H2-H1 change) would likely overstate trait stability.",
  "Opponent quality, pace, and roster or lineup changes across seasons are likely confounders of any year-over-year correlation."
 ],
 "uncertainties": [
  "Per-team-season variance of H2-H1 points allowed and the proportion attributable to true team differences are not known from the records.",
  "Whether the 2025-26 regular season partial data (complete from 2026-04-13) is included or excluded is not specified; the design assumes only complete seasons.",
  "No retrieved record reports a validation outcome (all validation_status NOT_RECORDED), so the reliability of the earlier family conclusions is itself unverified.",
  "Retrieval returned no record that directly tests team-level reliability; the evidence is indirect."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "Earlier records showed that play-type-label analyses failed verification (SF-APPA-030), that inferred-label analyses are unanswerable (SF-APPA-005), and that H2 suppression signals are largely RTM (SF-APPS-070). These changed the plan from a counter-strategy BEST/AVOID tier analysis to a raw H2-H1 points-allowed reliability test with explicit RTM and opponent-quality controls and a placebo. The decision moved from a tentative proceed to proceed_with_changes."
 },
 "testability": {
  "p_testable": 0.4,
  "blocking_constraints": [
   {
    "code": "RTM_SELECTION",
    "text": "H2-H1 change is dominated by regression to the mean (SF-APPS-070); without an RTM-matched baseline, reliability will be inflated."
   },
   {
    "code": "LABEL_ERROR",
    "text": "Play-type labels failed verification (SF-APPA-030); the test must use raw points and possessions, not derived labels."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
